"""Intel Arc GPU probe and PyTorch XPU install for the engine runtime.

Official ``pip install`` into system Python is invisible here: Qwen3 / SenseVoice /
Demucs import torch from ``transub-engine/runtime/python.exe`` only. NVIDIA CUDA
and AMD ROCm wheels do not run on Intel Arc. This module detects Arc and installs
official PyTorch XPU wheels into that interpreter.
"""

from __future__ import annotations

import os
import re
import shutil
import subprocess
import sys
from functools import lru_cache
from pathlib import Path
from typing import Any, Callable

ProgressCb = Callable[[dict[str, Any]], None]

XPU_INDEX_URL = "https://download.pytorch.org/whl/xpu"
_PYPI_EXTRA = "https://pypi.org/simple"
# Prefer a recent stable XPU build (cp312 win_amd64 available). Unpinned fallback
# still requires ``+xpu`` in the installed version string.
XPU_TORCH_PIN = "2.12.1+xpu"
XPU_VISION_PIN = "0.27.1+xpu"
XPU_AUDIO_PIN = "2.12.1+xpu"
_XPU_DLL_NAMES = ("c10_xpu.dll", "torch_xpu.dll", "ze_loader.dll")


def _emit(on_progress: ProgressCb | None, payload: dict[str, Any]) -> None:
    if not on_progress:
        return
    try:
        on_progress(payload)
    except Exception:
        pass


def _nvidia_smi_lists_gpu() -> bool:
    if not shutil.which("nvidia-smi"):
        return False
    try:
        out = subprocess.check_output(
            ["nvidia-smi", "--query-gpu=name", "--format=csv,noheader"],
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=5,
            stderr=subprocess.DEVNULL,
        )
        return any(str(line or "").strip() for line in str(out or "").splitlines())
    except Exception:
        return False


def _video_controllers() -> list[dict[str, Any]]:
    if os.name != "nt":
        return []
    try:
        out = subprocess.check_output(
            [
                "powershell.exe",
                "-NoProfile",
                "-Command",
                (
                    "Get-CimInstance Win32_VideoController | "
                    "Select-Object Name,AdapterRAM | ConvertTo-Json -Compress"
                ),
            ],
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=8,
            stderr=subprocess.DEVNULL,
        )
    except Exception:
        return []
    text = str(out or "").strip()
    if not text:
        return []
    import json

    try:
        data = json.loads(text)
    except Exception:
        return []
    if isinstance(data, dict):
        data = [data]
    if not isinstance(data, list):
        return []
    rows: list[dict[str, Any]] = []
    for row in data:
        if not isinstance(row, dict):
            continue
        rows.append(
            {
                "name": str(row.get("Name") or ""),
                "adapterRam": int(row.get("AdapterRAM") or 0),
            }
        )
    return rows


def is_intel_arc_name(name: str | None) -> bool:
    s = str(name or "")
    if not re.search(r"intel", s, re.I):
        return False
    if re.search(r"uhd\s*graphics|iris\s*(xe|plus)?|hd\s*graphics", s, re.I) and not re.search(
        r"\barc\b", s, re.I
    ):
        return False
    compact = re.sub(r"\((?:R|TM|C)\)", " ", s, flags=re.I)
    compact = re.sub(r"\s+", " ", compact)
    if re.search(r"\barc\s*(a|b)?\d{3,4}\b", compact, re.I):
        return True
    if re.search(r"\barc\s*graphics\b", compact, re.I):
        return True
    if re.search(r"battlemage|alchemist|xe[\s-]?hpg|xe[\s-]?lpg", compact, re.I):
        return True
    return False


def _clean_gpu_name(raw: str) -> str:
    return re.sub(r"\s+", " ", str(raw or "")).strip()


@lru_cache(maxsize=1)
def probe_intel_gpu() -> dict[str, Any]:
    """First Intel Arc adapter, or empty when NVIDIA owns the machine."""
    if _nvidia_smi_lists_gpu():
        return {}
    if os.name == "nt":
        for row in _video_controllers():
            raw = str(row.get("name") or "")
            if not is_intel_arc_name(raw):
                continue
            if re.search(r"microsoft\s*basic", raw, re.I):
                continue
            name = _clean_gpu_name(raw) or raw.strip()
            ram = int(row.get("adapterRam") or 0)
            vram_mb = int(ram // (1024 * 1024)) if ram > 0 else 0
            if vram_mb > 0 and vram_mb < 512:
                vram_mb = 0
            return {"name": name, "vramMb": vram_mb}
        return {}
    # Linux: lspci
    if shutil.which("lspci"):
        try:
            out = subprocess.check_output(
                ["lspci", "-nn"],
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=8,
                stderr=subprocess.DEVNULL,
            )
        except Exception:
            return {}
        for line in str(out or "").splitlines():
            if not re.search(r"VGA|3D|Display", line, re.I):
                continue
            if is_intel_arc_name(line):
                name = _clean_gpu_name(re.sub(r"^[^:]+:\s*", "", line))
                return {"name": name or "Intel Arc", "vramMb": 0}
    return {}


def intel_gpu_present() -> bool:
    return bool(probe_intel_gpu().get("name"))


def _torch_version_text() -> str:
    from .device import read_torch_version, torch_package_dir

    version_py = torch_package_dir() / "version.py"
    if version_py.is_file():
        try:
            text = version_py.read_text(encoding="utf-8", errors="replace")
        except Exception:
            text = ""
        for line in text.splitlines():
            if line.startswith("__version__"):
                parts = line.split("=", 1)
                if len(parts) == 2:
                    return parts[1].strip().strip("'\"").strip()
    return str(read_torch_version() or "")


def is_acceptable_xpu_torch_version(ver: str | None) -> bool:
    text = str(ver or "").lower()
    return "+xpu" in text or text.endswith(".xpu")


def torch_xpu_libs_present() -> bool:
    """True when this interpreter has an XPU torch wheel on disk (no LoadLibrary)."""
    from .device import torch_package_dir

    lib = torch_package_dir() / "lib"
    if not lib.is_dir():
        return False
    ver = _torch_version_text().lower()
    if "+xpu" not in ver and ".xpu" not in ver and not is_acceptable_xpu_torch_version(ver):
        return False
    # Require at least one XPU native library — version metadata alone is not enough.
    for name in _XPU_DLL_NAMES:
        if (lib / name).is_file():
            return True
    try:
        return any(lib.glob("*xpu*.dll")) or any(lib.glob("*xpu*.so*"))
    except Exception:
        return False


def torch_is_xpu() -> bool:
    if torch_xpu_libs_present():
        return True
    try:
        import torch

        xpu = getattr(torch, "xpu", None)
        return bool(xpu is not None and callable(getattr(xpu, "is_available", None)))
    except Exception:
        return False


def xpu_pip_specs(*, pinned: bool = True) -> list[str]:
    if pinned:
        return [
            f"torch=={XPU_TORCH_PIN}",
            f"torchvision=={XPU_VISION_PIN}",
            f"torchaudio=={XPU_AUDIO_PIN}",
        ]
    return ["torch", "torchvision", "torchaudio"]


def xpu_pip_command(*, python_exe: str = "") -> str:
    exe = str(python_exe or sys.executable).strip() or "python"
    specs = " ".join(f'"{item}"' for item in xpu_pip_specs(pinned=True))
    return (
        f'"{exe}" -m pip install --upgrade --force-reinstall '
        f"--index-url {XPU_INDEX_URL} --extra-index-url {_PYPI_EXTRA} {specs}"
        "\n# 必须用引擎 runtime\\python.exe；系统 Python 里的 XPU 包对本软件无效。"
        "\n# 成功标志：torch.__version__ 含 +xpu，且 torch.xpu.is_available() 为 True。"
    )


def _pin_numpy_for_numba() -> None:
    try:
        subprocess.run(
            [
                sys.executable,
                "-m",
                "pip",
                "install",
                "--upgrade",
                "numpy==2.4.6",
            ],
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=10 * 60,
            capture_output=True,
        )
    except Exception:
        pass


def _pip_install(
    specs: list[str],
    *,
    timeout_sec: float,
    force_reinstall: bool = True,
) -> tuple[int, str]:
    cmd = [
        sys.executable,
        "-u",
        "-m",
        "pip",
        "install",
        "--upgrade",
        *(["--force-reinstall"] if force_reinstall else []),
        "--index-url",
        XPU_INDEX_URL,
        "--extra-index-url",
        _PYPI_EXTRA,
        *specs,
    ]
    try:
        proc = subprocess.run(
            cmd,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=timeout_sec,
            capture_output=True,
        )
    except subprocess.TimeoutExpired as err:
        tail = str(err.stderr or err.stdout or "")[-800:]
        return 1, f"pip 超时：{tail}"
    except Exception as err:
        return 1, str(err)
    tail = ((proc.stderr or "") + "\n" + (proc.stdout or "")).strip()
    return int(proc.returncode or 0), tail[-1200:]


def install_torch_xpu(
    *,
    force: bool = True,
    on_progress: ProgressCb | None = None,
) -> dict[str, Any]:
    """Install official PyTorch XPU wheels into this engine interpreter."""
    if _nvidia_smi_lists_gpu():
        return {
            "ok": False,
            "skipped": True,
            "code": "NVIDIA_PRESENT",
            "message": "本机有 NVIDIA GPU，不安装 XPU PyTorch",
        }
    try:
        from .rocm_device import amd_gpu_present

        if amd_gpu_present():
            return {
                "ok": False,
                "skipped": True,
                "code": "AMD_PRESENT",
                "message": "本机有 AMD GPU，不安装 XPU PyTorch",
            }
    except Exception:
        pass
    probe = probe_intel_gpu()
    name = str(probe.get("name") or "Intel Arc")
    _ = force
    if torch_xpu_libs_present() and is_acceptable_xpu_torch_version(_torch_version_text()):
        return {
            "ok": True,
            "skipped": True,
            "code": "",
            "installed": ["torch"],
            "message": f"引擎运行时已有 XPU PyTorch（{name}）",
        }

    last_err = ""
    for pinned in (True,):
        specs = xpu_pip_specs(pinned=pinned)
        _emit(
            on_progress,
            {
                "type": "progress",
                "stage": "torch_xpu",
                "percent": 20,
                "detail": f"正在安装 XPU PyTorch（{name}）…",
                "mirror": XPU_INDEX_URL,
            },
        )
        code, tail = _pip_install(specs, timeout_sec=50 * 60)
        if code != 0:
            last_err = tail or f"pip exit {code}"
            continue
        ver = _torch_version_text()
        if not is_acceptable_xpu_torch_version(ver):
            last_err = (
                tail
                or f"pip 装到了非 XPU 的 torch（{ver or 'unknown'}），已拒绝。"
                "请确认能访问 download.pytorch.org/whl/xpu。"
            )
            continue
        if torch_xpu_libs_present():
            _pin_numpy_for_numba()
            ta_ok = True
            ta_err = ""
            try:
                import importlib
                importlib.invalidate_caches()
                importlib.import_module("torchaudio")
            except Exception as err:
                ta_ok = False
                ta_err = str(err)
            if not ta_ok:
                last_err = (
                    f"torch +xpu 已装但 torchaudio 无法 import：{ta_err}。"
                    "请重试自动修复或用手动 pip 命令。"
                )
                continue
            try:
                from .runtime_gpu import clear_probe_gpu_runtime_cache
                clear_probe_gpu_runtime_cache()
            except Exception:
                pass
            return {
                "ok": True,
                "code": "",
                "installed": specs,
                "version": ver,
                "message": f"已把 XPU PyTorch 装进引擎运行时（{ver}，{name}）",
                "pipCommand": xpu_pip_command(),
            }
        last_err = tail or "安装后仍未检测到 XPU torch"
    return {
        "ok": False,
        "code": "TORCH_XPU_INSTALL_FAILED",
        "message": last_err or "XPU PyTorch 安装失败",
        "pipCommand": xpu_pip_command(),
    }
